const c = $input.first().json;

const schemaFields = `{
  "description": "string, 2-3 sentences, what this course/degree is",
  "eligibility": "string, MUST begin by explicitly stating the exact minimum qualification level required to apply, using one of these precise phrasings: 'Must have passed 10th grade', 'Must have passed 12th grade (Science - PCM)', 'Must have passed 12th grade (Science - PCB)', 'Must have passed 12th grade (Commerce)', 'Must have passed 12th grade (any stream)', 'Must hold a graduate degree (any stream)', 'Must hold a graduate degree in a relevant field', or the correct equivalent for this course. After that opening statement, add minimum marks required and any entrance exam requirement.",
  "duration": "string, e.g. '4 years'",
  "entrance_exams": ["array of strings, key Indian entrance exams for this course"],
  "emerging_trends": "string, current trends in this field in India",
  "future_scope": "string, where this field is heading in India over next 5-10 years",
  "career_path": "string, typical career progression after this degree",
  "abroad_opportunities": "string, options for higher studies/work abroad after this course",
  "scholarships": "string, notable scholarships available for this course in India",
  "industry_demand": "string, current hiring demand in India for this field",
  "government_colleges_top3": ["array of up to 3 objects: {name, city, fees_annual_inr}"],
  "private_colleges_top3": ["array of up to 3 objects: {name, city, fees_annual_inr}"],
  "average_salary_inr": "number, average annual salary in India in INR",
  "highest_salary_inr": "number, highest reported annual salary in India in INR",
  "placement_percent": "number, typical placement rate percentage",
  "recruiters_top5": ["array of up to 5 top recruiter company names in India"],
  "faqs": ["array of up to 5 objects: {question, answer}"],
  "news": ["array of up to 3 objects: {headline, summary, url, published_date}"],
  "source_urls": ["array of URLs used to ground these facts"]
}`;

const GENERIC_UMBRELLA_DEGREES = ['ba', 'bsc', 'bcom', 'ma', 'msc', 'mcom', 'bs', 'ms'];
const isGenericUmbrella = GENERIC_UMBRELLA_DEGREES.includes(String(c.normalized_name || c.course_name || '').trim().toLowerCase());

const genericDegreeInstruction = isGenericUmbrella
  ? `

IMPORTANT: "${c.course_name}" is a broad umbrella degree name with NO specific specialization or stream given (unlike "BA Economics" or "B.Sc Data Science"). It covers many different specializations with very different outcomes. Do NOT silently pick one specialization's numbers and present them as if they apply generally. Instead: (1) in the description, explicitly mention it is a general/multidisciplinary degree covering several common specializations (name 3-4 popular ones), (2) for average_salary_inr, highest_salary_inr, and placement_percent, use realistic figures that represent a genuine overall/average across common specializations for this degree in India, not one narrow specialization's figures, (3) career_path and recruiters_top5 should reflect the range of outcomes across the common specializations, not just one.`
  : '';

const prompt = `You are researching the Indian graduation course "${c.course_name}" for a career guidance platform aimed at Indian Class 12 students and their parents.${genericDegreeInstruction}

Use web search to find CURRENT, ACCURATE, India-specific facts. Do not invent or guess numbers. If a fact cannot be verified, use null for that field rather than fabricating a value.

Return ONLY valid JSON matching this exact shape (no markdown, no commentary):
${schemaFields}`;

return [{ json: { course_name: c.course_name, normalized_name: c.normalized_name, rank_position: c.rank_position, prompt } }];

const src = $('Build Research Prompt').item.json;
const resp = $input.first().json;

try {

  // Read the JSON string from "output"
  const parsed = JSON.parse(resp.output);

  const fields = Object.keys(parsed)
    .filter(key => key !== 'source_urls')
    .map(key => ({
      field_key: key,
      field_value: parsed[key],
      model_used: 'gemini',
      source_urls: parsed.source_urls || []
    }));

  return [{
    json: {
      course_name: src.course_name,
      normalized_name: src.normalized_name,
      rank_position: src.rank_position,
      fields
    }
  }];

} catch (e) {

  return [{
    json: {
      error: true,
      message: "JSON parse failed: " + e.message
    }
  }];

}

const items = $input.all().map(function(i) { return i.json; });
const resp = items[0];

function extractText(resp) {
  const candidate = (resp.candidates && resp.candidates[0]) || null;
  if (!candidate) return '';
  const parts = (candidate.content && candidate.content.parts) || [];
  const texts = parts.map(function(p) { return p.text || ''; }).filter(Boolean);
  if (!texts.length) return '';
  const last = texts[texts.length - 1];
  const firstBrace = last.indexOf('{');
  const lastBrace = last.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return last.slice(firstBrace, lastBrace + 1);
  }
  const joined = texts.join('\n');
  const fb = joined.indexOf('{');
  const lb = joined.lastIndexOf('}');
  if (fb !== -1 && lb !== -1 && lb > fb) return joined.slice(fb, lb + 1);
  return last;
}

const text = extractText(resp);
return [{ json: { output: text } }];
